// src/shared/bluecc.ts
var BlueCcClient = class {
  constructor(tokenId, secretId, companyId) {
    this.tokenId = tokenId;
    this.secretId = secretId;
    this.companyId = companyId;
  }
  baseUrl = "https://api.blue.cc/graphql";
  async request(query, variables = {}, projectId) {
    const headers2 = {
      "Content-Type": "application/json",
      "X-Bloo-Token-ID": this.tokenId,
      "X-Bloo-Token-Secret": this.secretId
    };
    if (this.companyId) {
      headers2["X-Bloo-Company-ID"] = this.companyId;
    }
    if (projectId) {
      headers2["X-Bloo-Project-ID"] = projectId;
    }
    let response;
    try {
      response = await fetch(this.baseUrl, {
        method: "POST",
        headers: headers2,
        body: JSON.stringify({ query, variables }),
        signal: AbortSignal.timeout(2e4)
      });
    } catch (err) {
      throw new Error(err?.name === "TimeoutError" ? "Blue.cc didn't respond in time. Try again." : "Couldn't reach Blue.cc. Check your connection and try again.");
    }
    const result = await response.json().catch(() => null);
    if (!response.ok && !result?.errors) {
      throw new Error(response.status === 401 || response.status === 403 ? "Blue.cc rejected the API credentials. Check them in Blue.cc settings." : `Blue.cc returned an error (HTTP ${response.status}). Try again.`);
    }
    if (result?.errors?.length) {
      throw new Error(result.errors.map((e) => e.message).join(", "));
    }
    return result?.data ?? {};
  }
  async ensureCompanyId() {
    if (!this.companyId || this.companyId.includes(".")) {
      const companyQuery = `
        query GetCompanies {
          companies {
            items {
              id
            }
          }
        }
      `;
      const oldCompanyId = this.companyId;
      this.companyId = void 0;
      try {
        const companyData = await this.request(companyQuery);
        if (companyData.companies?.items?.length > 0) {
          this.companyId = companyData.companies.items[0].id;
        } else {
          this.companyId = oldCompanyId;
        }
      } catch (err) {
        this.companyId = oldCompanyId;
      }
    }
  }
  // Current User Profile
  async getMe() {
    const query = `
      query GetMe {
        currentUser {
          id
          firstName
          lastName
          email
          image {
            small
          }
        }
      }
    `;
    try {
      const data = await this.request(query);
      return data.currentUser;
    } catch (err) {
      console.warn("Failed to fetch currentUser with image field, trying fallback without image", err);
      const fallbackQuery = `
        query GetMeFallback {
          currentUser {
            id
            firstName
            lastName
            email
          }
        }
      `;
      try {
        const fallbackData = await this.request(fallbackQuery);
        return fallbackData.currentUser;
      } catch (e) {
        console.error("Failed GetMe completely", e);
        return null;
      }
    }
  }
  // Workspaces (Projects in Blue.cc schema)
  async getWorkspaces() {
    await this.ensureCompanyId();
    const targetCompanyIds = this.companyId ? [this.companyId] : [];
    if (targetCompanyIds.length === 0) return [];
    const query = `
      query GetWorkspaces($companyIds: [String!]!) {
        projectList(filter: { companyIds: $companyIds }, first: 50) {
          items {
            id
            name
            description
            archived
            updatedAt
            company {
              id
            }
          }
        }
      }
    `;
    const data = await this.request(query, { companyIds: targetCompanyIds });
    return (data.projectList?.items || []).map((item) => ({
      ...item,
      companyId: item.company?.id
    }));
  }
  async getWorkspaceContent(projectId, overrideCompanyId) {
    if (overrideCompanyId) {
      this.companyId = overrideCompanyId;
    } else {
      await this.ensureCompanyId();
    }
    const query = `
      query GetWorkspaceContent($projectId: String!) {
        todoLists(projectId: $projectId) {
          id
          title
          todos {
            id
            title
            done
            position
            text
            commentCount
            tags {
              id
              title
              color
            }
          }
        }
      }
    `;
    try {
      const data = await this.request(query, { projectId }, projectId);
      const fullLists = data.todoLists || [];
      return {
        id: projectId,
        lists: fullLists.map((list) => ({
          ...list,
          todos: list.todos || []
        }))
      };
    } catch (err) {
      console.error("Failed to fetch full workspace data:", err);
      throw err;
    }
  }
  async createWorkspace(name, description) {
    await this.ensureCompanyId();
    if (!this.companyId) {
      throw new Error("Could not automatically find your Company ID. Please add it manually in the settings.");
    }
    const query = `
      mutation CreateWorkspace($input: CreateProjectInput!) {
        createProject(input: $input) {
          id
          name
        }
      }
    `;
    const data = await this.request(query, {
      input: {
        name,
        description,
        companyId: this.companyId
      }
    });
    return data.createProject;
  }
  async updateWorkspace(projectId, name) {
    const query = `
      mutation EditWorkspace($input: EditProjectInput!) {
        editProject(input: $input) {
          id
          name
        }
      }
    `;
    const data = await this.request(query, { input: { id: projectId, name } });
    return data.editProject;
  }
  async archiveWorkspace(projectId) {
    const query = `
      mutation ArchiveWorkspace($id: String!) {
        archiveProject(id: $id)
      }
    `;
    const data = await this.request(query, { id: projectId });
    return data.archiveProject;
  }
  // Members Management
  async inviteUser(projectId, email) {
    const query = `
      mutation InviteUser($input: InviteUserInput!) {
        inviteUser(input: $input)
      }
    `;
    const data = await this.request(query, { input: { email, projectId } });
    return data.inviteUser;
  }
  async removeUser(projectId, userId) {
    const query = `
      mutation RemoveProjectUser($input: RemoveProjectUserInput!) {
        removeProjectUser(input: $input) {
          success
        }
      }
    `;
    const data = await this.request(query, { input: { projectId, userId } });
    return data.removeProjectUser;
  }
  // Webhooks
  async getWebhooks() {
    const query = `
      query GetWebhooks {
        webhooks {
          items {
            id
            url
            events
            isActive
          }
        }
      }
    `;
    const data = await this.request(query);
    return data.webhooks?.items || [];
  }
  async registerWebhook(projectId, url, events = ["*"]) {
    const query = `
      mutation CreateWebhook($input: CreateWebhookInput!) {
        createWebhook(input: $input) {
          id
          url
        }
      }
    `;
    const data = await this.request(query, { input: { url, events, projectId } });
    return data.createWebhook;
  }
  async getMentions(limit = 20) {
    const query = `
      query GetMentions($limit: Int) {
        mentions(filter: {}, limit: $limit) {
          items {
            id
            createdAt
            isRead
            mentioner {
              firstName
              lastName
            }
            targetWorkspace {
              id
              name
            }
          }
          pageInfo {
            totalItems
          }
        }
      }
    `;
    const data = await this.request(query, { limit });
    return {
      items: data.mentions?.items || [],
      total: data.mentions?.pageInfo?.totalItems || 0
    };
  }
  /**
   * Fetch all comments (with nested replies) for a given todo card.
   * Uses the Blue.cc commentList query with category=TODO.
   */
  async getTodoComments(todoId, projectId) {
    const query = `
      query GetTodoComments($categoryId: String!) {
        commentList(category: TODO, categoryId: $categoryId, first: 200) {
          totalCount
          comments {
            id
            text
            createdAt
            user {
              firstName
              lastName
            }
            replies {
              id
              text
              createdAt
              user {
                firstName
                lastName
              }
            }
          }
        }
      }
    `;
    const data = await this.request(query, { categoryId: todoId }, projectId);
    return {
      totalCount: data.commentList?.totalCount ?? 0,
      comments: data.commentList?.comments ?? []
    };
  }
  /**
   * Create a new comment or reply to an existing one.
   * To comment on a todo: categoryId = todoId, category = 'TODO'
   */
  async createComment(categoryId, category, text2, projectId, parentId) {
    const query = `
      mutation CreateComment($input: CreateCommentInput!) {
        createComment(input: $input) {
          id
          text
          createdAt
          user {
            firstName
            lastName
          }
        }
      }
    `;
    const escaped = text2.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    const inputPayload = {
      categoryId,
      category,
      text: text2,
      html: escaped.split(/\n{2,}/).map((p) => `<p>${p.replace(/\n/g, "<br>")}</p>`).join("")
    };
    if (parentId) {
      inputPayload.parentId = parentId;
    }
    const data = await this.request(query, { input: inputPayload }, projectId);
    return data.createComment;
  }
  /**
   * Get available users in the workspace for mentioning
   */
  async getWorkspaceUsers(projectId) {
    const query = `
      query GetWorkspaceUsers($projectId: String!) {
        projectUserList(projectId: $projectId, first: 100) {
          users {
            id
            firstName
            lastName
          }
        }
      }
    `;
    try {
      const data = await this.request(query, { projectId }, projectId);
      return data.projectUserList?.users || [];
    } catch (err) {
      console.warn("Failed to fetch workspace users via projectUserList", err);
      return [];
    }
  }
  /**
   * Move a todo to a different list (column).
   */
  async moveTodo(todoId, todoListId, projectId) {
    const query = `
      mutation MoveTodo($input: EditTodoInput!) {
        editTodo(input: $input) {
          id
        }
      }
    `;
    const data = await this.request(query, {
      input: {
        todoId,
        todoListId
      }
    }, projectId);
    return data.editTodo;
  }
};

